// testdataDir returns the path to internal/unpack/testdata/ which contains
// RAR test archives generated by scripts/gen_test_archives.sh.
func testdataDir(t *testing.T) string {
	t.Helper()
	// Tests run with cwd = package directory. Walk up to find testdata.
	dir, err := filepath.Abs("../unpack/testdata")
	if err != nil {
		t.Fatalf("abs path: %v", err)
	}
	if _, err := os.Stat(dir); err != nil {
		t.Skipf("testdata directory not found at %s (run scripts/gen_test_archives.sh)", dir)
	}
	return dir
}

// copyRAR copies a RAR file from testdata to workDir and returns the full path.
func copyRAR(t *testing.T, src, workDir, name string) string {
	t.Helper()
	data, err := os.ReadFile(filepath.Join(src, name))
	if err != nil {
		t.Fatalf("read %s: %v", name, err)
	}
	dst := filepath.Join(workDir, name)
	if err := os.WriteFile(dst, data, 0o644); err != nil {
		t.Fatalf("write %s: %v", name, err)
	}
	return dst
}

func TestDirectUnpack_SingleVolume_HappyPath(t *testing.T) {
	srcDir := testdataDir(t)
	workDir := t.TempDir()
	extractDir := t.TempDir()

	// Copy single-volume archive.
	volPath := copyRAR(t, srcDir, workDir, "single_rar5.rar")

	du := New(
		testLogger(t),
		"test-job",
		workDir,
		extractDir,
		Options{},
	)

	du.SetAllFilenames([]string{"single_rar5.rar"})

	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	du.Add(ctx, "single_rar5.rar", volPath)
	du.Wait()

	results := du.Results()
	failures := du.Failures()
	if len(failures) != 0 {
		t.Fatalf("expected no failures, got: %+v", failures)
	}
	if len(results) == 0 {
		t.Fatal("expected success, got 0 results")
	}

	// Verify extracted files exist.
	for _, name := range []string{"file1.txt", "file2.txt"} {
		path := filepath.Join(extractDir, name)
		if _, err := os.Stat(path); os.IsNotExist(err) {
			t.Errorf("extracted file not found: %s", name)
		}
	}

	// Check nested file.
	nested := filepath.Join(extractDir, "subdir", "nested.txt")
	if _, err := os.Stat(nested); os.IsNotExist(err) {
		t.Errorf("nested extracted file not found: subdir/nested.txt")
	}
}

func TestDirectUnpack_MultiVolume_AllPresent(t *testing.T) {
	srcDir := testdataDir(t)
	workDir := t.TempDir()
	extractDir := t.TempDir()

	// Copy all multi-volume parts.
	var names []string
	for i := 1; i <= 10; i++ {
		name := fmt.Sprintf("multi_new.part%02d.rar", i)
		copyRAR(t, srcDir, workDir, name)
		names = append(names, name)
	}

	du := New(
		testLogger(t),
		"test-job",
		workDir,
		extractDir,
		Options{},
	)

	du.SetAllFilenames(names)

	ctx, cancel := context.WithTimeout(context.Background(), 15*time.Second)
	defer cancel()

	// Feed all volumes at once.
	for _, name := range names {
		du.Add(ctx, name, filepath.Join(workDir, name))
	}

	du.Wait()

	results := du.Results()
	failures := du.Failures()
	if len(failures) != 0 {
		t.Fatalf("expected no failures, got: %+v", failures)
	}
	if len(results) == 0 {
		t.Fatal("expected success, got 0 results")
	}

	// Check that a file was extracted.
	ss := results["multi_new"]
	if len(ss.ExtractedFiles) == 0 {
		t.Error("expected extracted files")
	}
	if len(ss.RarParts) != 10 {
		t.Errorf("expected 10 rar parts, got %d", len(ss.RarParts))
	}
}

