// --- helpers ---

// waitForStarted returns an OnLine callback and a channel that is closed
// when the first line of extraction output is received, indicating the
// extraction has started. This replaces time.Sleep for test synchronization.
func waitForStarted() (func(string), <-chan struct{}) {
	ch := make(chan struct{})
	var once sync.Once
	return func(string) {
		once.Do(func() { close(ch) })
	}, ch
}

func fmtPart(n int) string {
	return fmt.Sprintf("movie.part%02d.rar", n)
}

func testLogger(t *testing.T) *slog.Logger {
	t.Helper()
	return slog.New(slog.NewTextHandler(os.Stderr, &slog.HandlerOptions{Level: slog.LevelDebug})).
		With("test", t.Name())
}

type logRecorder struct {
	mu   sync.Mutex
	logs []string
}

func (r *logRecorder) Enabled(ctx context.Context, l slog.Level) bool {
	return true
}

func (r *logRecorder) Handle(ctx context.Context, rec slog.Record) error {
	r.mu.Lock()
	r.logs = append(r.logs, rec.Message)
	r.mu.Unlock()
	return nil
}

func (r *logRecorder) WithAttrs(attrs []slog.Attr) slog.Handler {
	return r
}

func (r *logRecorder) WithGroup(name string) slog.Handler {
	return r
}

func TestDirectUnpack_Add_NoAllFilenames(t *testing.T) {
	recorder := &logRecorder{}
	logger := slog.New(recorder)
	du := New(logger, "test", t.TempDir(), t.TempDir(), Options{})

	ctx := context.Background()
	du.Add(ctx, "movie.part01.rar", "/tmp/movie.part01.rar")

	recorder.mu.Lock()
	defer recorder.mu.Unlock()
	for _, msg := range recorder.logs {
		if msg == "volume map built" {
			t.Error("expected volume map NOT to be built when allFilenames is empty")
		}
	}
}

func TestDirectUnpack_OnLinePanic(t *testing.T) {
	srcDir := testdataDir(t)
	workDir := t.TempDir()
	extractDir := t.TempDir()

	volPath := copyRAR(t, srcDir, workDir, "single_rar5.rar")

	du := New(
		testLogger(t),
		"test-job",
		workDir,
		extractDir,
		Options{
			OnLine: func(line string) {
				panic("simulated panic")
			},
		},
	)

	du.SetAllFilenames([]string{"single_rar5.rar"})

	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	du.Add(ctx, "single_rar5.rar", volPath)
	du.Wait()

	results := du.Results()
	if len(results) != 0 {
		t.Fatalf("expected 0 success sets after panic, got %d", len(results))
	}

	failures := du.Failures()
	f, ok := failures["single_rar5"]
	if !ok {
		t.Fatal("expected failure for single_rar5")
	}
	if !strings.Contains(f.Reason, "rarengine panic: simulated panic") {
		t.Errorf("expected failure reason to contain panic message, got: %q", f.Reason)
	}
}

// TestDirectUnpack_SkipsNonRAR5 verifies that DirectUnpack pre-checks the
// magic bytes of the first volume and skips (rather than fails) sets that
// aren't RAR5. rarengine only supports RAR5; legacy RAR3/4 archives
// (movie.rar/.r00/.r01/...) are common on Usenet and are handled by the
// normal unpack stage's external unrar fallback.
func TestDirectUnpack_SkipsNonRAR5(t *testing.T) {
	workDir := t.TempDir()
	extractDir := t.TempDir()

	// A minimal file starting with the 7-byte RAR3 magic signature
	// (Rar!\x1a\x07\x00). DirectUnpack must reject this before invoking
	// rarengine, so the remaining bytes don't need to form a valid archive.
	data := []byte{0x52, 0x61, 0x72, 0x21, 0x1a, 0x07, 0x00, 0xb2, 0xef, 0x73}
	volPath := filepath.Join(workDir, "legacy.rar")
	if err := os.WriteFile(volPath, data, 0o644); err != nil {
		t.Fatalf("write legacy.rar: %v", err)
	}

	du := New(
		testLogger(t),
		"test-job",
		workDir,
		extractDir,
		Options{},
	)

	du.SetAllFilenames([]string{"legacy.rar"})

	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	du.Add(ctx, "legacy.rar", volPath)
	du.Wait()

	if results := du.Results(); len(results) != 0 {
		t.Fatalf("expected no successful sets, got: %+v", results)
	}
	if failures := du.Failures(); len(failures) != 0 {
		t.Fatalf("expected no failed sets, got: %+v", failures)
	}

	skipped := du.Skipped()
	s, ok := skipped["legacy"]
	if !ok {
		t.Fatalf("expected 'legacy' to be recorded as skipped, got: %+v", skipped)
	}
	if !strings.Contains(s.Reason, "RAR3/4") {
		t.Errorf("expected skip reason to mention RAR3/4, got: %q", s.Reason)
	}
}
